local BORDER = { ["Southfury River"]=true, ["Lordamere Lake"]=true,
    ["Thondroril River"]=true, ["The Great Sea"]=true, ["The Veiled Sea"]=true }
local shores = {}
MF.GEOGRAPHY_NAME_ALIASES = { ["Dalaran"] = {279} }
local ALIASES = { [279] = { ["dalaran"]=true } }
local continents = {}
for _,row in pairs(MF.AREA_GEOGRAPHY) do
    if row[1] > 0 then continents[row[1]] = row[2] end
    if BORDER[row[3]] and row[1] > 0 then
        shores[row[3]] = shores[row[3]] or {}
        shores[row[3]][row[1]] = true
    end
end
function MF:AreaFitsMap(area,mapID)
    local override = self.AREA_MAP_OVERRIDES and self.AREA_MAP_OVERRIDES[area]
    if override then return override[mapID] == true end
    local row = self.AREA_GEOGRAPHY[area]
    if not row then return nil end
    -- A Forever client may reuse an old ID for a renamed custom area.
    -- English name disagreements make the baseline inconclusive, not wrong.
    local locale = type(GetLocale) == "function" and GetLocale()
    if (locale == "enUS" or locale == "enGB") and C_Map and type(C_Map.GetAreaInfo) == "function" then
        local name = C_Map.GetAreaInfo(area)
        if type(name) == "string" and name ~= "" and name:lower() ~= row[3]:lower()
            and not (ALIASES[area] and ALIASES[area][name:lower()]) then return nil end
    end
    if row[1] == mapID or row[2] == mapID then return true end
    if shores[row[3]] and shores[row[3]][mapID] then return true end
    if row[1] == 0 and row[2] > 0 and continents[mapID] == row[2] then return nil end
    -- Unknown custom/instance maps cannot be judged from this baseline.
    if not self.ZONE_IDS[mapID] and mapID ~= 1414 and mapID ~= 1415 then return nil end
    return false
end

function MF:AreaCandidateForMap(ids,mapID)
    local compatible,unknown
    for _,id in ipairs(ids) do
        local row = self.AREA_GEOGRAPHY[id]
        local fits = self:AreaFitsMap(id,mapID)
        if row and row[1] == mapID and fits then return id end
        if fits then compatible = compatible or id
        elseif fits == nil then unknown = unknown or id end
    end
    return compatible or unknown
end

